CREATE OR REPLACE FUNCTION dg_native_bill_refresh(action_value text,target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;state_value jsonb;created text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;state_value:=dg_native_bill_state(b.id);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_bills',b.id);UPDATE restaurant_bills SET status=state_value->>'status',attention_reason=state_value->>'attentionReason',settled_at=CASE WHEN settled_at IS NULL AND(state_value->>'settled')::boolean THEN created ELSE settled_at END,version=version+1,updated_at=created WHERE id=b.id;
 SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;
 IF(state_value->>'settled')::boolean AND(o.settlement_status<>'settled' OR dg_native_bill_order_fulfilled(o.id) AND o.status NOT IN('closed','cancelled')) THEN PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET settlement_status='settled',status=CASE WHEN dg_native_bill_order_fulfilled(id) AND status<>'cancelled' THEN 'closed' ELSE dg_native_order_status(id) END,version=version+1,updated_at=created WHERE id=o.id;END IF;
END;$dg$;

CREATE OR REPLACE FUNCTION dg_native_bill_order_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE actual_action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF table_value<>'restaurant_orders' THEN RETURN false;END IF;
 SELECT actual.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=j->>'id' AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id AND actual.restaurant_id=j->>'restaurant_id' AND actual.resource_id=j->>'party_id' AND actual.kind IN('bill_review','bill_receipt','order_receipt') ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;IF actual_action.id IS NULL THEN RETURN false;END IF;
 IF actual_action.kind='order_receipt' AND(j->>'settlement_status'<>'settled' OR j-ARRAY['settlement_status','status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['settlement_status','status','version','updated_at']) THEN RETURN false;END IF;
 IF operation_value<>'UPDATE' OR previous->>'settlement_status' NOT IN('unsettled','settled') OR j->>'settlement_status'<>'settled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['settlement_status','status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['settlement_status','status','version','updated_at'] OR j->>'updated_at'<>actual_action.created_at OR NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=j->>'id' AND bill.status IN('paid','partially_refunded','refunded','void') AND bill.attention_reason IS NULL AND bill.order_content_version=(j->>'content_version')::bigint) OR j->>'status' IS DISTINCT FROM(CASE WHEN previous->>'status'='cancelled' THEN 'cancelled' WHEN dg_native_bill_order_fulfilled(j->>'id') THEN 'closed' ELSE dg_native_order_status(j->>'id') END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order settlement requires actual verified bill facts and independently complete kitchen fulfillment';END IF;RETURN true;
END;$dg$;

CREATE FUNCTION dg_native_bill_order_changed(action_value text,order_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE bill_value text;
BEGIN SELECT bill_id INTO bill_value FROM _dg_native_bill_origins WHERE order_id=order_value;IF bill_value IS NOT NULL THEN PERFORM dg_native_bill_refresh(action_value,bill_value);END IF;END;$dg$;

CREATE OR REPLACE FUNCTION dg_native_bill_operation_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;manager_value boolean;active boolean;busy boolean;auto_value boolean;
BEGIN
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;manager_value:=dg_native_bill_manager(meta);active:=operation.status IN('pending','unknown','needs_attention') AND operation.send_attempts=1;busy:=operation.lease_token IS NOT NULL AND operation.lease_until>dg_native_dining_now() OR operation.next_action IS NOT NULL;auto_value:=meta->>'actorType'='staff' OR dg_native_order_source(meta,meta->>'partyId');
 RETURN jsonb_build_object('id',operation.id,'billId',operation.bill_id,'kind',operation.kind,'parentPaymentId',operation.parent_payment_id,'status',operation.status,'version',operation.version,'amountMinor',operation.amount_minor,'currency','CNY','reason',CASE WHEN operation.kind='refund' AND NOT manager_value THEN '门店经理核对退款' ELSE operation.reason END,'simulated',operation.simulated=1,'sendAttempts',operation.send_attempts,'simulateAttempts',operation.simulate_attempts,'lookups',operation.lookups,'nextAction',operation.next_action,'checkoutReady',operation.kind='payment' AND operation.status='pending' AND operation.remote_operation_id IS NOT NULL,'canSimulate',auto_value AND NOT busy AND operation.lease_token IS NULL AND dg_native_bill_action_reason(operation.id,'simulate',meta) IS NULL,'canQuery',active AND NOT busy AND auto_value,'canClose',active AND NOT busy AND operation.lease_token IS NULL AND auto_value AND dg_native_bill_action_reason(operation.id,'close',meta) IS NULL,'canWithdraw',operation.status='queued' AND operation.send_attempts=0 AND operation.lease_token IS NULL AND(operation.kind='payment' OR manager_value) AND auto_value,'refundableMinor',CASE WHEN operation.kind='payment' THEN coalesce(dg_native_bill_refundable(operation.id),0) ELSE 0 END,'remoteOperationId',operation.remote_operation_id,'remoteTransactionId',operation.remote_transaction_id,'errorMessage',operation.error_message,'createdAt',operation.created_at,'updatedAt',operation.updated_at);
END;$dg$;
